Okay so I've been thinking about this the entire time I've been in the shower because I felt like my entire answer prior earlier was just "haha it's hard good luck."
Instead of trying to overcomplicate anything with asynchronous stuff we just go along with the 60 frames per second game logic Occam's razor style. Every frame we check the AudioManager._bgmBuffer using .seek(). The bgmBuffer holds the object for the current bgm playing and using the .seek() method would tell us the time the bgm is currently at. So we can set loose a "hit" sprite as I'm gonna call it once .seek() reaches a certain point. By checking the bgmBuffer instead of using "wait x frames" we no longer run out of sync of the actual song.
JavaScript:
BattleManager.initMembers = function() {
    this._phase = "";
    this._inputting = false;
    this._canEscape = false;
    this._canLose = false;
    this._battleTest = false;
    this._eventCallback = null;
    this._preemptive = false;
    this._surprise = false;
    this._currentActor = null;
    this._actionForcedBattler = null;
    this._mapBgm = null;
    this._mapBgs = null;
    this._bgmTime = null; //<-- Adds variable to battle manager
    this._isBeatMap = false //<-- Adds bool to battle manager
    this._beatMap = []; //<-- To hold the actual beatMap
    this._actionBattlers = [];
    this._subject = null;
    this._action = null;
    this._targets = [];
    this._logWindow = null;
    this._spriteset = null;
    this._escapeRatio = 0;
    this._escaped = false;
    this._rewards = {};
    this._tpbNeedsPartyCommand = true;
};

const _BattleManager_update = BattleManager.update = function;
BattleManager.update = function(timeActive) { //This update happens EVERY frame
    if (this._isBeatMap) { //If isBeatMap it won't allow anyone to attack...probably
        this._bgmTime = AudioManager._bgmBuffer.seek(); //Updates time with bgm
    } else {_BattleManager_update.call(this, timeActive);}
};
At this point you would probably need to create a JSON file to hold in all your beat map information, like the id of the song, bpm, amount of hits, time of hits, types of hits, etc.
Then you would create a child sprite class that inherits the Sprite_Button class since it already has a method to process button presses.
JavaScript:
function Sprite_Beat() {
    this.initialize(...arguments);
}

Sprite_Beat.prototype = Object.create(Sprite_Button.prototype);
Sprite_Beat.prototype.constructor = Sprite_Beat;
//Since the button class inherits from the clickable class you're gonna have to deal with that
Sprite_Beat.prototype.initialize = function(JSON_Info) {
    Sprite_Button.prototype.initialize.call(this);
    this.beatType = JSON_Info[0];
    this.bpmTime = JSON_Info[1];
    this.row = JSON_Info[2];
    this._clickHandler = JSON_Info[3];
    this._holdHandler = JSON_Info[4];
    this.visible = false;
    this.velocity = 0; //Probably some more stuff to put ngl
    this.distanceToDestination = 0;
};

Sprite_Beat.prototype.buttonData = function() { //I'm not sure if this is the proper way
    const buttonTable = {                       //to overwrite a parent method
        cancel: { x: 0, w: 2 },
        pageup: { x: 2, w: 1 },
        pagedown: { x: 3, w: 1 },
        down: { x: 4, w: 1 },
        up: { x: 5, w: 1 },
        down2: { x: 6, w: 1 },
        up2: { x: 7, w: 1 },
        ok: { x: 8, w: 2 },
        menu: { x: 10, w: 1 }
    };
    return buttonTable[this._beatType];
}; //Stuff inherited from Sprite_Button, you should change it up

Sprite_Beat.prototype.holdHandler = function() {//You need to make this yourself
        this.holdHandler = method;
}

Sprite_Beat.prototype.onClick = function() { //Stuff that happens when the beat is clicked
    if (this._clickHandler && this.beatType === "click") {
        this._clickHandler();
    } else if (this._clickHandler && this.beatType === "hold") { //Added this to handle hold notes
         this.holdHandler();
    } else {
        Input.virtualClick(this._buttonType);
    }
};

Sprite_Beat.prototype.draw = function(x, y, width, height, color) {
        //Draw the actual sprite but idk what to put here
}
At that point you would revisit the BattleManager to create a new method that turns isBeatMap on, parses the JSON file, creates a bunch of Sprite_Beats. And call it when the battle starts or somehow find a way to call it midbattle if you want.
JavaScript:
let beatMapTroops = [1, 2, 3] //<-- Put all the troop ids you intend to put a beat map in

const _BattleManager_startBattle = BattleManager.startBattle;
BattleManager.startBattle = function() {
    _BattleManager_startBattle.call(this);
    if (beatMapTroops.include($gameTroop._troopId)) {//Checks the current troop to the array
        let JSON_Info = null;
        switch case($gameTroop._troopId) {
            case 1:
                JSON_Info = JSON_song1; //You need some sort of parsing method here
                break;
            case...
        }
        this._isBeatMap = true;
        for (let i = 0; i > JSON_Info.length; i++) { //Creates all the sprites for the beat map
            this._beatMap.push(new Sprite_Beat(JSON_Info[i]));}
    }
};
From this point you have to actually animate the sprites to the speed of the bgm most likely through matching velocity with .seek(). But after that I actually have no clue, knowledge, or experience on animation.
ADDITIONALLY, a lot AND I MEAN ALOT of this code is kinda wrong and janky and it's 3 AM. It's only really meant to get the point and intention across 'cause I really don't have that much knowledge on object inheritance, game logic, and ESPECIALLY on how to access JSON file information. I'd say I made some easy to mildly complex plugins, most taking around 30ish hours to make, but this easily crosses into the 50-150 hour territory unless you want to make some glorified QTE plugin. The only reason I'm able to spend so much time on plugins is because I truly enjoy creating something with my own hands. But you first have to learn a lot about programming but then you have to learn about how RPG Maker runs and then code and debug A LOT. This ain't the for the faint of heart and I wish you the best of luck. And if you do end up making it... you mind hooking a homie up with a free plugin??? I lowkey kinda need this too lol.
Edit: Btw I'm on mz so the code might be different from yours.

